import math
from hypothesis import given
import hypothesis.strategies as st
from solution import f


def reference(n):
    out = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            out.append(math.factorial(i))
        else:
            out.append(i * (i + 1) // 2)
    return out


def test_example_f5():
    assert f(5) == [1, 2, 6, 24, 15]


def test_example_n0_is_empty():
    assert f(0) == []


def test_example_n1():
    assert f(1) == [1]


def test_length_equals_n():
    for n in range(0, 15):
        assert len(f(n)) == n


@given(st.integers(min_value=0, max_value=30))
def test_property_length_equals_n(n):
    assert len(f(n)) == n


@given(st.integers(min_value=0, max_value=20))
def test_property_full_equivalence_to_reference(n):
    assert f(n) == reference(n)


@given(st.integers(min_value=1, max_value=20))
def test_property_odd_positions_are_triangular(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 1:
            assert res[i - 1] == i * (i + 1) // 2 == sum(range(1, i + 1))


@given(st.integers(min_value=2, max_value=20))
def test_property_even_positions_are_factorial(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 0:
            assert res[i - 1] == math.factorial(i)


@given(st.integers(min_value=1, max_value=20))
def test_property_first_element_is_one(n):
    assert f(n)[0] == 1


@given(st.integers(min_value=2, max_value=20))
def test_property_second_element_is_two(n):
    assert f(n)[1] == 2


@given(st.integers(min_value=1, max_value=20))
def test_property_prefix_consistency(n):
    full = f(n)
    for k in range(0, n + 1):
        assert full[:k] == f(k)


@given(st.integers(min_value=0, max_value=20))
def test_property_all_elements_positive_ints(n):
    res = f(n)
    for v in res:
        assert type(v) == int
        assert v >= 1
